            int[] coinValues=new int[stringArray.length];
            for(int a=0;a<stringArray.length;a++)
                coinValues[a]=(Integer.parseInt(stringArray[a]));

            System.out.println(count(coinValues, coinValues.length, sum));
		}
	}
}
